import{renderDiagram,renderCustomModel}from './visual.js?v=20261023-physicscomplete01';
import{foodAssays,assayResult,amylaseEndpoints,starchSample,endpointInterval,graphRateValid}from './digestion-practical-models.js?v=20261023-physicscomplete01';
const txt=(x,y,t,size=14)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="#f8f6f2" font-size="${size}">${t}</text>`;
const svg=(label,body)=>`<svg class="shell-diagram practical-diagram" viewBox="0 0 480 350" role="img" aria-label="${label}">${body}</svg>`;
const opts=(pairs,v)=>'<option value="">Choose…</option>'+pairs.map(([key,label])=>`<option value="${key}" ${String(key)===String(v)?'selected':''}>${label}</option>`).join('');
const note='<p class="diagram-caption">Original simulated observations and times. Apparatus, colours and volumes are schematic. This prepares for supervised school work; it does not establish hands-on practical competence.</p>';
export function showBioPractical(kind='food',w={}){
 if(kind.startsWith('food')){
  const a=foodAssays.find(x=>x.id===(w.assay||kind.split(':')[1]))||foodAssays[0],result=kind.includes(':')?assayResult(a.id,'positive',a.reagent,a.method):w.result,colour=result?.valid?result.colour:0xb7c8d6,observation=result?.observation||'Prepared sample · result not yet tested';
  renderCustomModel({name:a.name+' test',formula:observation,kicker:'FOOD-TEST SIMULATION',atoms:[],bonds:[],radius:3,viewKey:'food-assay',startPaused:true,note:'Use the written observation as well as colour',aria:a.name+' assay. '+observation,diagram:svg(a.name+' assay: '+observation,`<path d="M170 50V220A70 70 0 0 0 310 220V50" fill="#b7c8d6" fill-opacity=".12" stroke="#f8f6f2" stroke-width="3"/><path d="M174 150V220A66 66 0 0 0 306 220V150Z" fill="#${colour.toString(16).padStart(6,'0')}" opacity="${(result?.valid&&a.id==='lipid'&&!result.positive) ? .15 : .8}"/>`+txt(240,325,observation,14))+note,build:(group,T)=>{const glass=new T.Mesh(new T.CylinderGeometry(.55,.55,2.6,48,1,true),new T.MeshPhysicalMaterial({color:0xd4dfe7,transparent:true,opacity:.2,roughness:.1,side:T.DoubleSide,depthWrite:false}));group.add(glass);const liquid=new T.Mesh(new T.CylinderGeometry(.49,.49,1.35,48),new T.MeshStandardMaterial({color:colour,roughness:.28,transparent:true,opacity:result?.valid ? ((a.id==='lipid'&&!result.positive) ? .15 : .9) : .4}));liquid.position.y=-.55;group.add(liquid);if(result?.valid&&result.positive&&a.id==='sugar'){for(let i=0;i<14;i++){let grain=new T.Mesh(new T.SphereGeometry(.065,14,10),new T.MeshStandardMaterial({color:0xa64936,roughness:.8}));grain.position.set(Math.sin(i*2.4)*.35,-1.2+(i%3)*.03,Math.cos(i*2.4)*.35);group.add(grain);}}}});return;
 }
 if(kind==='graph'){
  const X=x=>70+(x-4)*85,Y=y=>265-y/.015*200;renderDiagram('Amylase rate comparison','Plot reciprocal time for each sampled endpoint',svg('Student graph of relative rate versus pH',`<path d="M70 50V265H420" stroke="#f8f6f2" fill="none"/>`+txt(240,25,'Relative rate / s⁻¹',14)+txt(245,330,'pH',15)+[4,6,8].map(x=>txt(X(x),290,String(x))).join('')+[0,.005,.010,.015].map(y=>txt(35,Y(y)+4,String(y),11)).join('')+Object.entries(w.points||{}).map(([x,y])=>`<circle cx="${X(Number(x))}" cy="${Y(Math.max(0,Math.min(.015,Number(y))))}" r="7" fill="#ed8b78" stroke="#f8f6f2"/>`).join(''))+note,'PLOT · INTERPRET');return;
 }
 if(kind==='amylase-example')w={ph:6,samples:{6:[30,60,90].map(t=>starchSample(6,t))}};const ph=Number(w.ph)||6,samples=w.samples?.[ph]||[],last=samples.at(-1);renderDiagram('Sample onto fresh iodine','pH'+ph+' · '+(last?last.time+'s':'Before mixing'),svg('Amylase samples tested with fresh iodine every30 seconds',`<rect x="35" y="45" width="410" height="230" rx="20" fill="#91a5b3" fill-opacity=".2" stroke="#f8f6f2"/>`+samples.map((s,i)=>`<circle cx="${100+(i%3)*140}" cy="${100+Math.floor(i/3)*100}" r="28" fill="${s.present?'#243348':'#bf8b50'}" stroke="#f8f6f2"/>`+txt(100+(i%3)*140,145+Math.floor(i/3)*100,s.time+'s · '+(s.present?'starch':'none'),12)).join('')+(!samples.length?txt(240,165,'Start timer as enzyme meets starch'):txt(240,320,last.observation,13)))+note,'30-SECOND SAMPLING');
}
export function mountBioPractical(l,p,root,{save,done,feedback}){
 const w=p.widget,$=s=>root.querySelector(s),food=l.widget==='food-tests',total=food?5:4;w.task??=0;w.passed??=[];const task=w.task%total;
 const field=(id,label,pairs,v)=>`<label class="field-label" for="${id}">${label}</label><select id="${id}" class="lab-select">${opts(pairs,v)}</select>`;
 const tail='<button class="secondary" id="checkBioPractical">Check reasoning</button><button class="secondary" id="nextBioPractical">Next challenge →</button><p id="bioPracticalProgress">'+w.passed.length+' / '+total+' complete</p>';
 const bind=id=>{$('#'+id).onchange=e=>{w[id]=e.target.value;save();};};let draw,valid,help;
 if(food){
  if(task===0){root.innerHTML='<p><b>1 / 5 · Prepare a fair comparison</b></p><p>Use separate labelled portions and clean equipment. For aqueous tests, crush a solid food with distilled water and filter. For the lipid test, extract a fresh portion with ethanol before adding water.</p>'+field('foodPrep','Prepare the sample',[['separate','Separate labelled extracts'],['all','Add every reagent together'],['taste','Taste the unknown food']],w.foodPrep)+field('foodSafety','Heating and protection',[['safe','Eye protection; heated water bath'],['flame','Heat every test directly in a flame'],['ethanol','Heat the ethanol mixture']],w.foodSafety)+field('foodControl','Negative control',[['water','Distilled water with same reagents'],['positive','Only a known positive food'],['none','No control']],w.foodControl)+tail;for(let k of ['foodPrep','foodSafety','foodControl'])bind(k);draw=()=>showBioPractical('food');valid=()=>w.foodPrep==='separate'&&w.foodSafety==='safe'&&w.foodControl==='water';help='Use separate labelled extracts and a distilled-water negative control. Wear eye protection; Benedict’s is heated in a water bath. Ethanol is flammable: keep it away from flames and never heat it.';
  }else{
   const a=foodAssays[task-1];w.assays??={};w.assays[a.id]??={sample:'positive',seen:[],result:null};const state=w.assays[a.id];root.innerHTML=`<p><b>${task+1} / 5 · Test for ${a.name.toLowerCase()}</b></p>`+field('assayReagent','Reagent',[['benedict','Benedict’s solution'],['iodine','Iodine solution'],['biuret','Biuret reagent'],['ethanol','Ethanol, then water']],state.reagent)+field('assayMethod','Method',[['bath','Heat using a water bath'],['room','Mix; no heating required'],['extract','Extract in ethanol; add water'],['flame','Heat directly in a flame']],state.method)+field('assaySample','Known comparison sample',[['positive','Known positive'],['negative','Water negative control']],state.sample)+'<button class="secondary" id="runAssay">Run test →</button><p id="assayReadout" aria-live="polite"></p><ul id="assayHistory"></ul>'+field('assayMeaning','What does a positive result establish?',[['present','Substance detected'],['amount','Exact amount of that substance'],['all','Every nutrient is present']],state.meaning)+tail;
   draw=()=>{showBioPractical('food',{assay:a.id,result:state.result});$('#assayReadout').textContent=state.result?.observation||'Select a reagent, method and comparison sample.';$('#assayHistory').innerHTML=state.seen.map(k=>'<li>'+(k==='positive'?'Known positive: '+a.positive:'Negative control: '+a.negative)+'</li>').join('');};for(let [id,key]of [['assayReagent','reagent'],['assayMethod','method'],['assaySample','sample'],['assayMeaning','meaning']])$('#'+id).onchange=e=>{state[key]=e.target.value;if(key!=='meaning')state.result=null;save();draw();};$('#runAssay').onclick=()=>{if(!['positive','negative'].includes(state.sample)){feedback('Choose a comparison sample.',true);return;}state.result=assayResult(a.id,state.sample,state.reagent,state.method);if(state.result.valid&&!state.seen.includes(state.sample))state.seen.push(state.sample);save();draw();if(!state.result.valid)feedback('Choose the appropriate reagent and method before interpreting the observation. Do not heat ethanol or use a direct flame.',true);};valid=()=>state.seen.includes('positive')&&state.seen.includes('negative')&&state.meaning==='present'&&state.reagent===a.reagent&&state.method===a.method;help='Compare a valid known positive with the negative control using the correct reagent/method. Qualitative tests detect a substance; they do not establish its exact amount.';
  }
 }else{
  w.samples??={4:[],6:[],8:[]};w.ph??=6;
  if(task===0){root.innerHTML='<p><b>1 / 4 · Plan a pH investigation</b></p>'+field('amylaseVariable','Change…',[['ph','Buffer pH'],['all','pH and enzyme amount together'],['temperature','Temperature only']],w.amylaseVariable)+field('amylaseControl','Keep constant…',[['matched','Temperature + amounts matched'],['ph','Only the buffer colour'],['none','Nothing else']],w.amylaseControl)+field('amylaseHeat','Control temperature with…',[['bath','Water bath at chosen temperature'],['flame','A flame under each tube'],['room','Unrecorded room conditions']],w.amylaseHeat)+field('amylaseStart','Start the timer…',[['mix','When amylase meets starch'],['iodine','After the first negative result'],['end','After all tests finish']],w.amylaseStart)+tail;for(let k of ['amylaseVariable','amylaseControl','amylaseHeat','amylaseStart'])bind(k);valid=()=>w.amylaseVariable==='ph'&&w.amylaseControl==='matched'&&w.amylaseHeat==='bath'&&w.amylaseStart==='mix';draw=()=>showBioPractical('amylase',w);help='Change buffered pH while matching temperature, enzyme/starch volumes and concentrations. Equilibrate in the same chosen water bath; time starts as enzyme and starch mix.';
  }else if(task===1){root.innerHTML='<p><b>2 / 4 · Sample every30 seconds</b></p><p>Simulated matched mixtures at37°C. Transfer a fresh drop from the reacting mixture to a fresh iodine well every30s. Iodine stays out of the reaction tube. Start with a starch-positive check.</p>'+field('samplePH','Buffer pH',[[4,'pH4'],[6,'pH6'],[8,'pH8']],w.ph)+'<button class="secondary" id="sampleAmylase">Take next30s sample →</button><p id="sampleReadout" aria-live="polite"></p><ul id="sampleHistory"></ul>'+field('sampleEndpoint','Endpoint observation',[['brown','Iodine remains orange-brown'],['black','First blue-black sample'],['purple','Protein turns purple']],w.sampleEndpoint)+tail;$('#samplePH').onchange=e=>{w.ph=Number(e.target.value)||6;save();draw();};$('#sampleEndpoint').onchange=e=>{w.sampleEndpoint=e.target.value;save();};draw=()=>{showBioPractical('amylase',w);const s=w.samples[w.ph],last=s.at(-1);$('#sampleReadout').textContent=last?last.time+'s: '+last.observation:'Time0 starch check is blue-black. Take the next sample at30s.';$('#sampleHistory').innerHTML=Object.keys(amylaseEndpoints).map(ph=>{const s=w.samples[ph],last=s.at(-1);return '<li>pH'+ph+': '+(!last?'not sampled':last.present?'starch still detected at'+last.time+'s':'first no-starch sample at'+last.time+'s')+'</li>';}).join('');};$('#sampleAmylase').onclick=()=>{const s=w.samples[w.ph],last=s.at(-1);if(last&&!last.present){feedback('Endpoint recorded. Compare another pH using the same sampling interval.');return;}const time=(last?.time||0)+30;s.push(starchSample(w.ph,time));save();draw();};valid=()=>[4,6,8].every(ph=>w.samples[ph].at(-1)?.present===false)&&w.sampleEndpoint==='brown';help='Sample all three pH mixtures every30s until iodine stays orange-brown. Blue-black means starch is still detected. Use fresh iodine wells, not iodine added to the reacting mixture.';
  }else if(task===2){root.innerHTML='<p><b>3 / 4 · Repeat and calculate</b></p><p>Original repeated endpoint times at one pH:90,120 and90s. Calculate the mean time, then1/mean time. The reactions use the same endpoint.</p><label class="field-label" for="meanEndpoint">Mean endpoint time / s</label><input class="lab-select" type="number" id="meanEndpoint" value="'+(w.meanEndpoint??'')+'"><label class="field-label" for="relativeEndpoint">1/mean time / s⁻¹</label><input class="lab-select" type="number" step="any" id="relativeEndpoint" value="'+(w.relativeEndpoint??'')+'">'+field('repeatReason','Repeats help…',[['reliability','Assess variation across repeats'],['exact','Prove an exact true time'],['bias','Remove every systematic error']],w.repeatReason)+tail;for(let k of ['meanEndpoint','relativeEndpoint'])$('#'+k).oninput=e=>{w[k]=e.target.value;save();};bind('repeatReason');valid=()=>Number(w.meanEndpoint)===100&&Math.abs(Number(w.relativeEndpoint)-.01)<.00001&&w.repeatReason==='reliability';draw=()=>showBioPractical('amylase',w);help='Mean=(90+120+90)÷3=100s;1/100=0.010s⁻¹. Repeats show variability but cannot guarantee accuracy or remove systematic error.';
  }else{w.points??={};root.innerHTML='<p><b>4 / 4 · Plot and interpret</b></p><p>Single supplied endpoints: pH4=180s, pH6=90s, pH8=150s. Plot1/time at each pH, then judge the sampling resolution. These points do not establish an exact universal optimum.</p>'+field('plotPH','pH to plot',[[4,'pH4'],[6,'pH6'],[8,'pH8']],w.plotPH||4)+'<label class="field-label" for="plotRate">Relative rate / s⁻¹</label><input class="lab-select" type="number" step="any" min="0" max="0.015" id="plotRate" value="'+(w.plotRate??'')+'"><button class="secondary" id="recordRate">Plot point →</button><ul id="ratePoints"></ul>'+field('rateConclusion','Fastest tested pH',[['six','pH6 in these supplied trials'],['all','Every enzyme has optimum pH6'],['four','pH4 because its time is longest']],w.rateConclusion)+field('sampleInterval','First negative at90s after positive at60s means…',[['interval','Endpoint after60s, by90s'],['exact','Exact endpoint90.000s'],['zero','No starch was ever present']],w.sampleInterval)+tail;for(let k of ['rateConclusion','sampleInterval'])bind(k);$('#plotPH').onchange=e=>{w.plotPH=Number(e.target.value)||4;save();};$('#plotRate').oninput=e=>{w.plotRate=e.target.value;save();};$('#recordRate').onclick=()=>{const n=Number(w.plotRate);if(!String(w.plotRate??'').trim()||!Number.isFinite(n)||n<0||n>.015){feedback('Enter a finite rate from0 to0.015s⁻¹ for this axis.',true);return;}w.points[w.plotPH||4]=n;save();draw();};draw=()=>{showBioPractical('graph',w);$('#ratePoints').innerHTML=Object.entries(w.points).map(([ph,v])=>'<li>pH'+ph+': '+v+'s⁻¹</li>').join('');};valid=()=>[4,6,8].every(ph=>Object.hasOwn(w.points,ph)&&graphRateValid(ph,w.points[ph]))&&w.rateConclusion==='six'&&w.sampleInterval==='interval';help='Plot1/180≈0.0056,1/90≈0.0111 and1/150≈0.0067s⁻¹. The fastest tested mixture is pH6. A positive60s then negative90s sample places the endpoint in that interval; shorter sampling improves resolution.';
  }
 }
 $('#checkBioPractical').onclick=()=>{if(!valid()){feedback(help,true);return;}if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;done();}save();$('#bioPracticalProgress').textContent=w.passed.length+' / '+total+' complete';feedback('Observation, method and reasoning agree.');};$('#nextBioPractical').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge first.',true);return;}w.task=(task+1)%total;save();feedback('');mountBioPractical(l,p,root,{save,done,feedback});};draw();
}
